actions.script:
import org.moqui.resource.ResourceReference
import groovy.xml.MarkupBuilder

String finalXml = rawXmlContent
if (!finalXml && serviceAst) {
    StringWriter writer = new StringWriter()
    MarkupBuilder xml = new MarkupBuilder(writer)

    def renderAstNode
    renderAstNode = { Map node, MarkupBuilder builder ->
        String tag = node.name ?: 'service'
        Map attrs = node.attributes ?: [:]
        List children = node.children ?: []

        if (children.isEmpty() && !node.text) {
            builder."${tag}"(attrs)
        } else if (children.isEmpty() && node.text) {
            builder."${tag}"(attrs, node.text)
        } else {
            builder."${tag}"(attrs) {
                children.each { child ->
                    if (child instanceof Map) renderAstNode(child, builder)
                }
            }
        }
    }

    renderAstNode(serviceAst, xml)
    finalXml = '<?xml version="1.0" encoding="UTF-8"?>\n' + writer.toString()
}

if (finalXml && artifactUri) {
    ResourceReference rr = ec.resource.getLocationReference(artifactUri)
    rr.putText(finalXml)
    status = "SUCCESS"
    message = "Service definition written to disk."
} else {
    status = "ERROR"
    message = "No XML or AST provided."
}

long start = System.currentTimeMillis()
boolean beganTx = false
Map inMap = testParameters ?: [:]

try {
    if (rollbackTransaction) {
        beganTx = ec.transaction.begin(60)
    }

    Map res = ec.service.sync().name(serviceName).parameters(inMap).call()
    results = res
    status = (res.containsKey("errorMessage") || res.containsKey("error")) ? "FAILURE" : "SUCCESS"

} catch (Throwable t) {
    status = "ERROR"
    errorMessage = t.getMessage() ?: t.toString()
    StringWriter sw = new StringWriter()
    t.printStackTrace(new PrintWriter(sw))
    errorStackTrace = sw.toString()
    ec.logger.warn("Test execution error on service [${serviceName}]: ${errorMessage}")
} finally {
    if (rollbackTransaction && beganTx) {
        try {
            ec.transaction.rollback(true, "Rollback transient test execution", null)
        } catch (Exception e) {
            ec.logger.warn("Error rolling back test transaction: ${e.message}")
        }
    }
    executionTimeMs = System.currentTimeMillis() - start
}
